typedef unsigned long long u64;
typedef unsigned int u32;
i64 m1(u64 a, u64 b, u32 s) { return (a + b) * 3; }
i64 m2(u64 a, u64 b, u32 s) { return (a + b) * 3 - (a << s); }
i64 m3(u64 a, u64 b, u32 s) { return (b >> (s & 31)); }
i64 m4(u64 a, u64 b, u32 s) { return (a + b) * 3 - (a << s) ^ (b >> (s & 31)); }

