// tcc wasm32 backend × tcc's own tests2 corpus.
// Compiles each tests2/*.c with the fork's wasm32 tcc, runs it with
// Node WASI + the shell's c-runtime env shim, compares stdout to .expect.
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { execFileSync, execFile } from "node:child_process";
import { createCRuntime, CExit } from "/root/src/sh2runtime/src/c-runtime.js";

const TCC = "/root/src/tinycc-wasm/build-wasm32/tcc";
const INC = "/root/src/tinycc-wasm/include";
const WASI_INC = "/usr/include/wasm32-wasi";
const CORPUS = "/root/src/tinycc-wasm/tests/tests2";
const OUT = "/tmp/tcc-corpus";

const enc = new TextEncoder(), dec = new TextDecoder();

function runOne(cFile, expect) {
  const name = cFile.replace(/\.c$/, "");
  const wasm = `${OUT}/${name}.wasm`;
  // 1. compile
  let compOut, compErr = "";
  try {
    compOut = execFileSync(TCC, ["-nostdinc", `-I${WASI_INC}`, `-I${INC}`, cFile, "-o", wasm], { encoding: "utf8" });
  } catch (e) {
    return { kind: "REFUSE", note: (e.stderr || e.stdout || "").split("\n").filter(Boolean).pop()?.slice(0, 70) };
  }
  // 2. instantiate
  let module;
  try {
    module = new WebAssembly.Module(readFileSync(wasm));
  } catch (e) {
    return { kind: "COMPILE-OUT", note: e.message.slice(0, 70) };
  }
  const imports = WebAssembly.Module.imports(module);
  const memRef = { memory: null };
  let stdout = "";
  const envRt = createCRuntime({
    getMem: () => new Uint8Array(memRef.memory.buffer),
    memory: () => memRef.memory,
    out: (t) => { stdout += t; },
    err: (t) => { stdout += t; },
    table: () => null,
  });
  // only the env functions this module imports (same trimming the shell does)
  const want = new Set(imports.filter(i => i.module === "env").map(i => i.name));
  const env = {};
  for (const [k, v] of Object.entries(envRt)) if (want.has(k)) env[k] = v;
  const impObj = { env };
  const wasiImports = imports.filter(i => i.module === "wasi_snapshot_preview1");
  if (wasiImports.length) {
    impObj.wasi_snapshot_preview1 = {
      proc_exit: (code) => { throw new CExit(code); },
      fd_write: () => 0, fd_close: () => 0, fd_seek: () => 0, fd_read: () => 0,
    };
  }
  let exitCode = 0;
  try {
    const instance = new WebAssembly.Instance(module, impObj);
    memRef.memory = instance.exports.memory;
    if (instance.exports._start) instance.exports._start();
    else if (instance.exports.main) instance.exports.main();
  } catch (e) {
    if (e instanceof CExit) { exitCode = e.code; }
    else if (e instanceof WebAssembly.RuntimeError) return { kind: "RUN-CRASH", note: e.message.slice(0, 70) };
    else return { kind: "RUN-ERR", note: String(e).slice(0, 70) };
  }
  const got = stdout.replace(/\n$/, "");
  const wantOut = expect.replace(/\n$/, "");
  if (got === wantOut) return { kind: "PASS" };
  // find first diff
  const gl = got.split("\n"), wl = wantOut.split("\n");
  let d = 0; while (d < Math.min(gl.length, wl.length) && gl[d] === wl[d]) d++;
  return { kind: "WRONG", note: `line ${d + 1}: got "${(gl[d]||"").slice(0,40)}" want "${(wl[d]||"").slice(0,40)}"` };
}

// main
if (!/^--run=/.test(process.argv[2] || "")) {
  // list mode
  const files = readdirSync(CORPUS).filter(f => f.endsWith(".c") && f !== "42test.h");
  const rows = files.map(f => {
    const expect = readFileSync(`${CORPUS}/${f.replace(/\.c$/, ".expect")}`, "utf8");
    const r = runOne(`${CORPUS}/${f}`, expect);
    return { f, ...r };
  });
  const counts = {};
  for (const r of rows) counts[r.kind] = (counts[r.kind] || 0) + 1;
  console.log(`\n=== tcc wasm32 × tests2 corpus (${rows.length} tests) ===`);
  console.log(Object.entries(counts).map(([k, v]) => `${k}: ${v}`).join("  "));
  console.log("─".repeat(70));
  for (const r of rows) {
    console.log(`${(r.kind + "      ").slice(0, 12)} ${r.f}${r.note ? "  — " + r.note : ""}`);
  }
  writeFileSync("/tmp/tcc-corpus-report.json", JSON.stringify(rows, null, 1));
}

